"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[128],{85:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-01-tools-data</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-1-инструменты-данные-и-первый-ориентир">Лабораторная\nработа 1. Инструменты, данные и первый ориентир</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>первое занятие курса, <strong>до</strong> лекции 1</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>нет — работа опирается только на линейную алгебру и матанализ</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно + домашняя работа (3–4 ч)</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Пройти путь от сырой таблицы до матрицы «объекты–признаки», пригодной\nдля обучения, и построить ориентир, с которым дальше сравниваются все\nмодели курса. Попутно освоить векторизацию в NumPy: весь курс записан в\nматричной форме, и она понадобится на каждом занятии.</p>\n<h2 id="как-устроено-занятие">Как устроено занятие</h2>\n<p>Ноутбук разбирается в аудитории: код запускается и обсуждается по\nходу. Большая часть ячеек уже написана — их нужно <strong>прочитать и\nзапустить</strong>, разобравшись, что происходит и почему.</p>\n<p>Ячейки, помеченные <code># ✍ ЗАДАНИЕ НА СЕМИНАРЕ</code>, заполняются\nсамостоятельно прямо на занятии; их немного, и каждая занимает несколько\nстрок. Ячейки <strong>Вывод</strong> — тоже ваши: короткий ответ своими\nсловами на поставленный вопрос.</p>\n<p>Дома выполняется отдельный ноутбук <code>lab01_homework.ipynb</code>\n— там задания крупнее и делать их нужно самому.</p>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже) — и на семинаре, и в домашней\nработе.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<h2 id="как-устроен-практикум">Как устроен практикум</h2>\n<p>Девять занятий, чередующихся с лекциями, причём курс начинается\nпрактикумом:</p>\n<pre><code>Зан. 1 → Лек 1 → Зан. 2 → Лек 2 → … → Лек 8 → Зан. 9</code></pre>\n<p>Значит, занятие\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">k+1</annotation></semantics></math>\nзакрепляет лекцию\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>.\nСегодняшнее идёт до первой лекции и теории курса не требует — это\nподготовка инструментов и данных.</p>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb2-7"><a href="#cb2-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-8"><a href="#cb2-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb2-9"><a href="#cb2-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-10"><a href="#cb2-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb2-11"><a href="#cb2-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb2-12"><a href="#cb2-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb2-13"><a href="#cb2-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-14"><a href="#cb2-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-15"><a href="#cb2-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb2-16"><a href="#cb2-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb2-17"><a href="#cb2-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb2-18"><a href="#cb2-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb2-19"><a href="#cb2-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb2-20"><a href="#cb2-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb2-21"><a href="#cb2-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb2-22"><a href="#cb2-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb2-23"><a href="#cb2-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb2-24"><a href="#cb2-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb2-25"><a href="#cb2-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb2-26"><a href="#cb2-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-27"><a href="#cb2-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-28"><a href="#cb2-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb2-29"><a href="#cb2-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb2-30"><a href="#cb2-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-31"><a href="#cb2-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb2-32"><a href="#cb2-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb2-33"><a href="#cb2-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-34"><a href="#cb2-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb2-35"><a href="#cb2-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb2-36"><a href="#cb2-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb2-37"><a href="#cb2-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb2-38"><a href="#cb2-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb2-39"><a href="#cb2-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb2-40"><a href="#cb2-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb2-41"><a href="#cb2-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb2-42"><a href="#cb2-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb2-43"><a href="#cb2-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-44"><a href="#cb2-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb2-45"><a href="#cb2-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-46"><a href="#cb2-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> make_table</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-векторизация-вместо-циклов">Часть 1. Векторизация вместо\nциклов</h1>\n<p>Курс записан в матричных обозначениях: матрица «объекты–признаки»\nразмера\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℓ</mi><mo>×</mo><mi>n</mi></mrow><annotation encoding="application/x-tex">\\ell\\times n</annotation></semantics></math>\n— это массив NumPy формы <code>(l, n)</code>. Правило, которое сэкономит\nдесятки часов: <strong>если вы пишете цикл по объектам выборки, почти\nнаверняка есть векторизованная запись — короче и в десятки раз\nбыстрее.</strong></p>\n<p>Понадобится матрица попарных квадратов расстояний\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>D</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><msub><mi>a</mi><mi>i</mi></msub><mo>−</mo><msub><mi>b</mi><mi>j</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">D_{ij} = \\|a_i - b_j\\|^2</annotation></semantics></math>.\nСчитать её двойным циклом можно, но не нужно:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>a</mi><mo>−</mo><mi>b</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>a</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>−</mo><mn>2</mn><mo stretchy="false" form="prefix">⟨</mo><mi>a</mi><mo>,</mo><mi>b</mi><mo stretchy="false" form="postfix">⟩</mo><mi>+</mi><mo stretchy="false" form="postfix">∥</mo><mi>b</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\|a - b\\|^2 = \\|a\\|^2 - 2\\langle a, b\\rangle + \\|b\\|^2 .\n</annotation></semantics></math></p>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> dists_vectorized(A, B):</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Попарные квадраты расстояний без единого цикла.</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">    Подсказка: np.sum(A**2, axis=1)[:, None] -- столбец квадратов норм,</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a><span class="co">    A @ B.T -- матрица скалярных произведений, сложить поможет broadcasting.</span></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки). В конце верните np.maximum(D, 0.0) -- см. вывод ниже.</span></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="cell007" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> time</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> dists_loops(A, B):</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Тот же результат двойным циклом -- эталон корректности.&quot;&quot;&quot;</span></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>    D <span class="op">=</span> np.empty((A.shape[<span class="dv">0</span>], B.shape[<span class="dv">0</span>]))</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> i <span class="kw">in</span> <span class="bu">range</span>(A.shape[<span class="dv">0</span>]):</span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a>        <span class="cf">for</span> j <span class="kw">in</span> <span class="bu">range</span>(B.shape[<span class="dv">0</span>]):</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>            diff <span class="op">=</span> A[i] <span class="op">-</span> B[j]</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a>            D[i, j] <span class="op">=</span> diff <span class="op">@</span> diff</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> D</span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a>A, B <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">400</span>, <span class="dv">20</span>)), rng.normal(size<span class="op">=</span>(<span class="dv">300</span>, <span class="dv">20</span>))</span>\n<span id="cb5-15"><a href="#cb5-15" aria-hidden="true" tabindex="-1"></a>t0 <span class="op">=</span> time.perf_counter()<span class="op">;</span> D_loop <span class="op">=</span> dists_loops(A, B)<span class="op">;</span> t_loop <span class="op">=</span> time.perf_counter() <span class="op">-</span> t0</span>\n<span id="cb5-16"><a href="#cb5-16" aria-hidden="true" tabindex="-1"></a>t0 <span class="op">=</span> time.perf_counter()<span class="op">;</span> D_vec <span class="op">=</span> dists_vectorized(A, B)<span class="op">;</span> t_vec <span class="op">=</span> time.perf_counter() <span class="op">-</span> t0</span>\n<span id="cb5-17"><a href="#cb5-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-18"><a href="#cb5-18" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;максимальное расхождение: </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">abs</span>(D_loop <span class="op">-</span> D_vec)<span class="sc">.</span><span class="bu">max</span>()<span class="sc">:.2e}</span><span class="ss">&quot;</span>)</span>\n<span id="cb5-19"><a href="#cb5-19" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;цикл </span><span class="sc">{</span>t_loop <span class="op">*</span> <span class="dv">1000</span><span class="sc">:.0f}</span><span class="ss"> мс, векторизация </span><span class="sc">{</span>t_vec <span class="op">*</span> <span class="dv">1000</span><span class="sc">:.0f}</span><span class="ss"> мс &quot;</span></span>\n<span id="cb5-20"><a href="#cb5-20" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;-&gt; ускорение в </span><span class="sc">{</span>t_loop <span class="op">/</span> t_vec<span class="sc">:.0f}</span><span class="ss"> раз&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Во сколько раз быстрее? Почему расхождение не\nстрого нулевое и зачем <code>np.maximum(D, 0)</code>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell009" class="cell markdown">\n<hr />\n<h1 id="часть-2-что-лежит-в-таблице">Часть 2. Что лежит в таблице</h1>\n<p>Данные индивидуальные и сознательно «грязные» — примерно такой вид\nимеет выгрузка из реальной информационной системы.</p>\n</div>\n<div id="cell010" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>df_raw, meta <span class="op">=</span> make_table(variant)</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>TASK, TARGET <span class="op">=</span> meta[<span class="st">&quot;task&quot;</span>], meta[<span class="st">&quot;target&quot;</span>]</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>meta[<span class="st">&#39;domain&#39;</span>]<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>df_raw<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss"> объектов, </span><span class="sc">{</span>df_raw<span class="sc">.</span>shape[<span class="dv">1</span>] <span class="op">-</span> <span class="dv">1</span><span class="sc">}</span><span class="ss"> признаков&quot;</span>)</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;тип задачи: </span><span class="sc">{</span>TASK<span class="sc">}</span><span class="ss">, целевая переменная: </span><span class="sc">{</span>TARGET<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>df_raw.head(<span class="dv">5</span>)</span></code></pre></div>\n</div>\n<div id="cell011" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Сводка по столбцам: тип, число уникальных значений, пропуски</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>info <span class="op">=</span> pd.DataFrame({</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;тип&quot;</span>: df_raw.dtypes.astype(<span class="bu">str</span>),</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;уникальных&quot;</span>: df_raw.nunique(),</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;доля пропусков, %&quot;</span>: (df_raw.isna().mean() <span class="op">*</span> <span class="dv">100</span>).<span class="bu">round</span>(<span class="dv">1</span>),</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;пример&quot;</span>: df_raw.<span class="bu">apply</span>(<span class="kw">lambda</span> s: s.dropna().iloc[<span class="dv">0</span>] <span class="cf">if</span> s.notna().<span class="bu">any</span>() <span class="cf">else</span> <span class="va">None</span>),</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>display(info)</span></code></pre></div>\n</div>\n<div id="cell012" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какие столбцы прочитаны как\n<code>object</code>, хотя по смыслу числовые? Какие бесполезны уже\nсейчас?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell013" class="cell markdown">\n<hr />\n<h1 id="часть-3-приводим-в-порядок">Часть 3. Приводим в порядок</h1>\n<p>Тип признака определяет, что с ним вообще можно делать:</p>\n<table>\n<colgroup>\n<col style="width: 25%" />\n<col style="width: 25%" />\n<col style="width: 25%" />\n<col style="width: 25%" />\n</colgroup>\n<thead>\n<tr>\n<th>Тип</th>\n<th>Множество значений</th>\n<th>Пример</th>\n<th>Что осмысленно</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>бинарный</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">{</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\{0,1\\}</annotation></semantics></math></td>\n<td>«есть балкон»</td>\n<td>всё</td>\n</tr>\n<tr>\n<td>номинальный</td>\n<td>конечное, без порядка</td>\n<td>«район»</td>\n<td>сравнение на равенство</td>\n</tr>\n<tr>\n<td>порядковый</td>\n<td>конечное, упорядоченное</td>\n<td>«ремонт: без / косм. / евро»</td>\n<td>сравнение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mo>≤</mo><annotation encoding="application/x-tex">\\le</annotation></semantics></math></td>\n</tr>\n<tr>\n<td>количественный</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℝ</mi><annotation encoding="application/x-tex">\\mathbb{R}</annotation></semantics></math></td>\n<td>«площадь»</td>\n<td>арифметика</td>\n</tr>\n</tbody>\n</table>\n<p>Ошибка здесь стоит дорого: закодировав «район» числами 1..5, мы\nсообщим модели, что «Юг» больше «Севера», а «Запад» — ровно посередине\nмежду ними.</p>\n</div>\n<div id="cell014" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> to_numeric_safe(s: pd.Series, threshold: <span class="bu">float</span> <span class="op">=</span> <span class="fl">0.2</span>) <span class="op">-&gt;</span> pd.Series:</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Строковый столбец -&gt; числовой, если он на самом деле числовой.&quot;&quot;&quot;</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">if</span> s.dtype <span class="op">!=</span> <span class="bu">object</span>:</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a>        <span class="cf">return</span> s</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки):</span></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>    <span class="co">#   1) убрать пробелы (в т.ч. неразрывные) и заменить &#39;,&#39; на &#39;.&#39;;</span></span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">#   2) pd.to_numeric(..., errors=&quot;coerce&quot;);</span></span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>    <span class="co">#   3) если доля непреобразованных НЕПУСТЫХ значений &gt; threshold,</span></span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a>    <span class="co">#      столбец действительно нечисловой -- вернуть s без изменений.</span></span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="cell015" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> df_raw.copy()</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> df.columns:</span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>    before <span class="op">=</span> df[col].dtype</span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>    df[col] <span class="op">=</span> to_numeric_safe(df[col])</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">if</span> before <span class="op">!=</span> df[col].dtype:</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a>        <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>col<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>before<span class="sc">}</span><span class="ss"> -&gt; </span><span class="sc">{</span>df[col]<span class="sc">.</span>dtype<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a><span class="co"># Категории приходят в разном написании: «Москва», «москва », «МОСКВА»</span></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a>cat_cols <span class="op">=</span> meta[<span class="st">&quot;categorical&quot;</span>]</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;</span><span class="ch">\\n</span><span class="st">было категорий:&quot;</span>, {c: df[c].nunique() <span class="cf">for</span> c <span class="kw">in</span> cat_cols})</span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> cat_cols:</span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a>    df[col] <span class="op">=</span> df[col].astype(<span class="bu">object</span>).<span class="bu">map</span>(</span>\n<span id="cb9-13"><a href="#cb9-13" aria-hidden="true" tabindex="-1"></a>        <span class="kw">lambda</span> v: v.strip().lower() <span class="cf">if</span> <span class="bu">isinstance</span>(v, <span class="bu">str</span>) <span class="cf">else</span> v)</span>\n<span id="cb9-14"><a href="#cb9-14" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;стало категорий:&quot;</span>, {c: df[c].nunique() <span class="cf">for</span> c <span class="kw">in</span> cat_cols})</span></code></pre></div>\n</div>\n<div id="cell016" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Дубликаты строк и вырожденные признаки</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;полных дубликатов: </span><span class="sc">{</span>df<span class="sc">.</span>duplicated()<span class="sc">.</span><span class="bu">sum</span>()<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> df.drop_duplicates().reset_index(drop<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a>drop <span class="op">=</span> [c <span class="cf">for</span> c <span class="kw">in</span> df.columns.drop(TARGET)</span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> df[c].nunique(dropna<span class="op">=</span><span class="va">False</span>) <span class="op">&lt;=</span> <span class="dv">1</span></span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>        <span class="kw">or</span> df[c].value_counts(normalize<span class="op">=</span><span class="va">True</span>, dropna<span class="op">=</span><span class="va">False</span>).iloc[<span class="dv">0</span>] <span class="op">&gt;</span> <span class="fl">0.99</span>]</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;вырожденные признаки (удаляем): </span><span class="sc">{</span>drop<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> df.drop(columns<span class="op">=</span>drop)</span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;осталось: </span><span class="sc">{</span><span class="bu">len</span>(df)<span class="sc">}</span><span class="ss"> объектов, </span><span class="sc">{</span>df<span class="sc">.</span>shape[<span class="dv">1</span>] <span class="op">-</span> <span class="dv">1</span><span class="sc">}</span><span class="ss"> признаков&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell017" class="cell markdown">\n<h3 id="выбросы-и-опечатки">Выбросы и опечатки</h3>\n<p>Два рабочих правила поиска выбросов:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mi>x</mi><mo>−</mo><mover><mi>x</mi><mo accent="true">¯</mo></mover><mo stretchy="false" form="prefix">|</mo><mo>&gt;</mo><mn>3</mn><mi>σ</mi></mrow><annotation encoding="application/x-tex">|x - \\overline x| &gt; 3\\sigma</annotation></semantics></math>\n(страдает от самих выбросов — они раздувают\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>σ</mi><annotation encoding="application/x-tex">\\sigma</annotation></semantics></math>)\nи межквартильное\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>∉</mo><mo stretchy="false" form="prefix">[</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>−</mo><mn>1.5</mn><mspace width="0.167em"></mspace><mrow><mi mathvariant="normal">I</mi><mi mathvariant="normal">Q</mi><mi mathvariant="normal">R</mi></mrow><mo>,</mo><mspace width="0.222em"></mspace><msub><mi>Q</mi><mn>3</mn></msub><mo>+</mo><mn>1.5</mn><mspace width="0.167em"></mspace><mrow><mi mathvariant="normal">I</mi><mi mathvariant="normal">Q</mi><mi mathvariant="normal">R</mi></mrow><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">x \\notin [Q_1 - 1.5\\,\\mathrm{IQR},\\ Q_3 + 1.5\\,\\mathrm{IQR}]</annotation></semantics></math>\n(устойчивое).</p>\n<p>Среди выбросов есть особая группа: значения, превышающие 99-й\nперцентиль примерно в 100 раз. Это не редкие объекты, а\n<strong>потерянный десятичный разделитель</strong> — их надо чинить, а\nне удалять.</p>\n</div>\n<div id="cell018" class="cell code">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>num_cols <span class="op">=</span> df.select_dtypes(include<span class="op">=</span><span class="st">&quot;number&quot;</span>).columns.drop(TARGET)</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>report <span class="op">=</span> []</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> num_cols:</span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a>    s <span class="op">=</span> df[col].dropna()</span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a>    q1, q3 <span class="op">=</span> s.quantile([<span class="fl">0.25</span>, <span class="fl">0.75</span>])<span class="op">;</span> iqr <span class="op">=</span> q3 <span class="op">-</span> q1</span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a>    report.append({<span class="st">&quot;признак&quot;</span>: col,</span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a>                   <span class="st">&quot;IQR-правило&quot;</span>: <span class="bu">int</span>(((s <span class="op">&lt;</span> q1 <span class="op">-</span> <span class="fl">1.5</span> <span class="op">*</span> iqr) <span class="op">|</span> (s <span class="op">&gt;</span> q3 <span class="op">+</span> <span class="fl">1.5</span> <span class="op">*</span> iqr)).<span class="bu">sum</span>()),</span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a>                   <span class="st">&quot;3 sigma&quot;</span>: <span class="bu">int</span>((np.<span class="bu">abs</span>(s <span class="op">-</span> s.mean()) <span class="op">&gt;</span> <span class="dv">3</span> <span class="op">*</span> s.std()).<span class="bu">sum</span>()),</span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a>                   <span class="st">&quot;макс / q_0.99&quot;</span>: <span class="bu">round</span>(s.<span class="bu">max</span>() <span class="op">/</span> s.quantile(<span class="fl">0.99</span>), <span class="dv">1</span>)})</span>\n<span id="cb11-10"><a href="#cb11-10" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(report).set_index(<span class="st">&quot;признак&quot;</span>))</span></code></pre></div>\n</div>\n<div id="cell019" class="cell code">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Чиним опечатки масштаба и смотрим, как меняется связь признака с целью</span></span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> num_cols:</span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>    mask <span class="op">=</span> df[col] <span class="op">&gt;</span> <span class="dv">30</span> <span class="op">*</span> df[col].quantile(<span class="fl">0.99</span>)</span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>    <span class="cf">if</span> mask.<span class="bu">sum</span>():</span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a>        before <span class="op">=</span> df[[col, TARGET]].corr().iloc[<span class="dv">0</span>, <span class="dv">1</span>]</span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>        df.loc[mask, col] <span class="op">=</span> df.loc[mask, col] <span class="op">/</span> <span class="fl">100.0</span></span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a>        <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>col<span class="sc">}</span><span class="ss">: исправлено </span><span class="sc">{</span>mask<span class="sc">.</span><span class="bu">sum</span>()<span class="sc">}</span><span class="ss"> значений, &quot;</span></span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a>              <span class="ss">f&quot;корреляция с целью </span><span class="sc">{</span>before<span class="sc">:+.3f}</span><span class="ss"> -&gt; </span><span class="sc">{</span>df[[col, TARGET]]<span class="sc">.</span>corr()<span class="sc">.</span>iloc[<span class="dv">0</span>, <span class="dv">1</span>]<span class="sc">:+.3f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell020" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какое правило нашло больше выбросов и почему?\nЧто произошло с корреляцией после исправления опечаток?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell021" class="cell markdown">\n<hr />\n<h1 id="часть-4-признак-которого-не-должно-быть">Часть 4. Признак,\nкоторого не должно быть</h1>\n<p>В таблице есть столбец <code>id</code>. Формально это число, и его\nможно подать в модель. Посмотрим, что будет.</p>\n</div>\n<div id="cell022" class="cell code">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> cross_val_score</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.tree <span class="im">import</span> DecisionTreeClassifier, DecisionTreeRegressor</span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a>model, scoring <span class="op">=</span> ((DecisionTreeRegressor(max_depth<span class="op">=</span><span class="dv">4</span>, random_state<span class="op">=</span>RANDOM_STATE), <span class="st">&quot;r2&quot;</span>)</span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a>                  <span class="cf">if</span> TASK <span class="op">==</span> <span class="st">&quot;regression&quot;</span></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a>                  <span class="cf">else</span> (DecisionTreeClassifier(max_depth<span class="op">=</span><span class="dv">4</span>, random_state<span class="op">=</span>RANDOM_STATE), <span class="st">&quot;roc_auc&quot;</span>))</span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a>score <span class="op">=</span> cross_val_score(model, df[[<span class="st">&quot;id&quot;</span>]], df[TARGET], cv<span class="op">=</span><span class="dv">5</span>, scoring<span class="op">=</span>scoring)</span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;качество (</span><span class="sc">{</span>scoring<span class="sc">}</span><span class="ss">) по ОДНОМУ признаку id: </span><span class="sc">{</span>score<span class="sc">.</span>mean()<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell023" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a>ax.scatter(df[<span class="st">&quot;id&quot;</span>], df[TARGET], s<span class="op">=</span><span class="dv">6</span>, alpha<span class="op">=</span><span class="fl">0.35</span>, color<span class="op">=</span><span class="st">&quot;#C97A2B&quot;</span>)</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;id&quot;</span>)<span class="op">;</span> ax.set_ylabel(TARGET)</span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Целевая переменная против идентификатора&quot;</span>)</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> df.drop(columns<span class="op">=</span>[<span class="st">&quot;id&quot;</span>])</span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;столбец id удалён&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Откуда взялась такая связь и почему\n<code>id</code> необходимо удалить, хотя он улучшает качество?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell025" class="cell markdown">\n<hr />\n<h1 id="часть-5-разбиение-и-предобработка-без-утечек">Часть 5. Разбиение\nи предобработка без утечек</h1>\n<p>Главное правило всего курса:</p>\n<blockquote>\n<p>Все параметры предобработки — средние, дисперсии, медианы для\nзаполнения пропусков, список категорий — вычисляются <strong>только по\nобучающей части</strong> и затем применяются к контрольной.</p>\n</blockquote>\n<p>Иначе информация о контрольной выборке просачивается в обучение, и\nоценка качества оказывается завышенной. Насколько именно — измерим на\nзанятии 5.</p>\n<p>Технически это делает <code>Pipeline</code> с\n<code>ColumnTransformer</code>: они запоминают параметры на\n<code>fit</code> и применяют их в <code>transform</code>.</p>\n</div>\n<div id="cell026" class="cell code">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>X, y <span class="op">=</span> df.drop(columns<span class="op">=</span>[TARGET]), df[TARGET]</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a>num_cols_final <span class="op">=</span> <span class="bu">list</span>(X.select_dtypes(include<span class="op">=</span><span class="st">&quot;number&quot;</span>).columns)</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a>cat_cols_final <span class="op">=</span> [c <span class="cf">for</span> c <span class="kw">in</span> X.columns <span class="cf">if</span> c <span class="kw">not</span> <span class="kw">in</span> num_cols_final]</span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a>X_train, X_test, y_train, y_test <span class="op">=</span> train_test_split(</span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a>    X, y, test_size<span class="op">=</span><span class="fl">0.25</span>, random_state<span class="op">=</span>RANDOM_STATE,</span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a>    stratify<span class="op">=</span>y <span class="cf">if</span> TASK <span class="op">==</span> <span class="st">&quot;classification&quot;</span> <span class="cf">else</span> <span class="va">None</span>)</span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;обучающая </span><span class="sc">{</span>X_train<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss">, контрольная </span><span class="sc">{</span>X_test<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb15-11"><a href="#cb15-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;числовых </span><span class="sc">{</span><span class="bu">len</span>(num_cols_final)<span class="sc">}</span><span class="ss">, категориальных </span><span class="sc">{</span><span class="bu">len</span>(cat_cols_final)<span class="sc">}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell027" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.compose <span class="im">import</span> ColumnTransformer</span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.impute <span class="im">import</span> SimpleImputer</span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> OneHotEncoder, StandardScaler</span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: соберите ColumnTransformer из двух веток:</span></span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a><span class="co">#   числовые (num_cols_final)  -&gt; SimpleImputer(strategy=&quot;median&quot;) + StandardScaler</span></span>\n<span id="cb16-10"><a href="#cb16-10" aria-hidden="true" tabindex="-1"></a><span class="co">#   категории (cat_cols_final) -&gt; SimpleImputer(strategy=&quot;most_frequent&quot;)</span></span>\n<span id="cb16-11"><a href="#cb16-11" aria-hidden="true" tabindex="-1"></a><span class="co">#                                 + OneHotEncoder(handle_unknown=&quot;ignore&quot;,</span></span>\n<span id="cb16-12"><a href="#cb16-12" aria-hidden="true" tabindex="-1"></a><span class="co">#                                                 sparse_output=False)</span></span>\n<span id="cb16-13"><a href="#cb16-13" aria-hidden="true" tabindex="-1"></a>preprocessor <span class="op">=</span> ...</span></code></pre></div>\n</div>\n<div id="cell028" class="cell code">\n<div class="sourceCode" id="cb17"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb17-1"><a href="#cb17-1" aria-hidden="true" tabindex="-1"></a>X_train_t <span class="op">=</span> preprocessor.fit_transform(X_train)   <span class="co"># fit ТОЛЬКО на обучающей части</span></span>\n<span id="cb17-2"><a href="#cb17-2" aria-hidden="true" tabindex="-1"></a>X_test_t <span class="op">=</span> preprocessor.transform(X_test)         <span class="co"># на контрольной -- только transform</span></span>\n<span id="cb17-3"><a href="#cb17-3" aria-hidden="true" tabindex="-1"></a>feature_names <span class="op">=</span> preprocessor.get_feature_names_out()</span>\n<span id="cb17-4"><a href="#cb17-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb17-5"><a href="#cb17-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;матрица объектов-признаков: </span><span class="sc">{</span>X_train_t<span class="sc">.</span>shape<span class="sc">}</span><span class="ss"> (было </span><span class="sc">{</span>X_train<span class="sc">.</span>shape[<span class="dv">1</span>]<span class="sc">}</span><span class="ss"> столбцов)&quot;</span>)</span>\n<span id="cb17-6"><a href="#cb17-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;первые признаки:&quot;</span>, <span class="bu">list</span>(feature_names[:<span class="dv">5</span>]))</span></code></pre></div>\n</div>\n<div id="cell029" class="cell markdown">\n<hr />\n<h1 id="часть-6-ориентир-с-чем-сравнивать-модели">Часть 6. Ориентир: с\nчем сравнивать модели</h1>\n<p>Прежде чем радоваться качеству, надо знать, сколько даёт\n<strong>тривиальный ответ</strong> — константа. Для регрессии это\nсреднее, для классификации — самый частый класс.</p>\n<p>Строгие определения функции потерь и риска будут на лекции 1; пока\nпользуемся привычными:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">M</mi><mi mathvariant="normal">S</mi><mi mathvariant="normal">E</mi></mrow><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munder><mo>∑</mo><mi>i</mi></munder><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mo>,</mo><mspace width="2.0em"></mspace><msup><mi>R</mi><mn>2</mn></msup><mo>=</mo><mn>1</mn><mo>−</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><mo stretchy="false" form="prefix">(</mo><mover><mi>y</mi><mo accent="true">¯</mo></mover><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\mathrm{MSE} = \\frac1\\ell\\sum_i (a(x_i) - y_i)^2, \\qquad\nR^2 = 1 - \\frac{\\sum_i (a(x_i) - y_i)^2}{\\sum_i (\\overline y - y_i)^2}.\n</annotation></semantics></math></p>\n<p>Заметьте:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">R^2 = 0</annotation></semantics></math>\n— это ровно качество константного прогноза средним.</p>\n</div>\n<div id="cell030" class="cell code">\n<div class="sourceCode" id="cb18"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb18-1"><a href="#cb18-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.dummy <span class="im">import</span> DummyClassifier, DummyRegressor</span>\n<span id="cb18-2"><a href="#cb18-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LinearRegression, LogisticRegression</span>\n<span id="cb18-3"><a href="#cb18-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> accuracy_score, r2_score, roc_auc_score</span>\n<span id="cb18-4"><a href="#cb18-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb18-5"><a href="#cb18-5" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> TASK <span class="op">==</span> <span class="st">&quot;regression&quot;</span>:</span>\n<span id="cb18-6"><a href="#cb18-6" aria-hidden="true" tabindex="-1"></a>    pairs <span class="op">=</span> [(<span class="st">&quot;константа (среднее)&quot;</span>, DummyRegressor(strategy<span class="op">=</span><span class="st">&quot;mean&quot;</span>)),</span>\n<span id="cb18-7"><a href="#cb18-7" aria-hidden="true" tabindex="-1"></a>             (<span class="st">&quot;линейная регрессия&quot;</span>, LinearRegression())]</span>\n<span id="cb18-8"><a href="#cb18-8" aria-hidden="true" tabindex="-1"></a>    score <span class="op">=</span> <span class="kw">lambda</span> m: {<span class="st">&quot;R2&quot;</span>: r2_score(y_test, m.predict(X_test_t))}</span>\n<span id="cb18-9"><a href="#cb18-9" aria-hidden="true" tabindex="-1"></a><span class="cf">else</span>:</span>\n<span id="cb18-10"><a href="#cb18-10" aria-hidden="true" tabindex="-1"></a>    pairs <span class="op">=</span> [(<span class="st">&quot;константа (частый класс)&quot;</span>, DummyClassifier(strategy<span class="op">=</span><span class="st">&quot;most_frequent&quot;</span>)),</span>\n<span id="cb18-11"><a href="#cb18-11" aria-hidden="true" tabindex="-1"></a>             (<span class="st">&quot;логистическая регрессия&quot;</span>, LogisticRegression(max_iter<span class="op">=</span><span class="dv">2000</span>))]</span>\n<span id="cb18-12"><a href="#cb18-12" aria-hidden="true" tabindex="-1"></a>    score <span class="op">=</span> <span class="kw">lambda</span> m: {<span class="st">&quot;accuracy&quot;</span>: accuracy_score(y_test, m.predict(X_test_t)),</span>\n<span id="cb18-13"><a href="#cb18-13" aria-hidden="true" tabindex="-1"></a>                       <span class="st">&quot;ROC-AUC&quot;</span>: roc_auc_score(y_test, m.predict_proba(X_test_t)[:, <span class="dv">1</span>])}</span>\n<span id="cb18-14"><a href="#cb18-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb18-15"><a href="#cb18-15" aria-hidden="true" tabindex="-1"></a>results <span class="op">=</span> {name: score(m.fit(X_train_t, y_train)) <span class="cf">for</span> name, m <span class="kw">in</span> pairs}</span>\n<span id="cb18-16"><a href="#cb18-16" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(results).T.<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell031" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько модель лучше константы? Что\nозначает <code>accuracy = 0.8</code> у константного классификатора при\nнесбалансированных классах?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell032" class="cell code">\n<div class="sourceCode" id="cb19"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb19-1"><a href="#cb19-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Сохраняем подготовленные данные: понадобятся на следующих занятиях</span></span>\n<span id="cb19-2"><a href="#cb19-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pathlib, joblib</span>\n<span id="cb19-3"><a href="#cb19-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb19-4"><a href="#cb19-4" aria-hidden="true" tabindex="-1"></a>data_dir <span class="op">=</span> pathlib.Path(<span class="st">&quot;data&quot;</span>)<span class="op">;</span> data_dir.mkdir(exist_ok<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb19-5"><a href="#cb19-5" aria-hidden="true" tabindex="-1"></a>np.savez_compressed(data_dir <span class="op">/</span> <span class="st">&quot;prepared.npz&quot;</span>, X_train<span class="op">=</span>X_train_t, X_test<span class="op">=</span>X_test_t,</span>\n<span id="cb19-6"><a href="#cb19-6" aria-hidden="true" tabindex="-1"></a>                    y_train<span class="op">=</span>np.asarray(y_train), y_test<span class="op">=</span>np.asarray(y_test),</span>\n<span id="cb19-7"><a href="#cb19-7" aria-hidden="true" tabindex="-1"></a>                    feature_names<span class="op">=</span>np.asarray(feature_names, dtype<span class="op">=</span><span class="bu">object</span>))</span>\n<span id="cb19-8"><a href="#cb19-8" aria-hidden="true" tabindex="-1"></a>joblib.dump(preprocessor, data_dir <span class="op">/</span> <span class="st">&quot;preprocessor.joblib&quot;</span>)</span>\n<span id="cb19-9"><a href="#cb19-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;сохранено:&quot;</span>, <span class="op">*</span>[p.name <span class="cf">for</span> p <span class="kw">in</span> <span class="bu">sorted</span>(data_dir.iterdir())])</span></code></pre></div>\n</div>\n<div id="cell033" class="cell markdown">\n<h2 id="итоги-занятия">Итоги занятия</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Чем номинальный признак отличается от порядкового и почему их нельзя\nкодировать одинаково? Приведите пример из своей таблицы.</li>\n<li>Что такое утечка данных? Приведите два примера: один из вашей\nтаблицы, второй — придуманный для задачи «вернёт ли клиент кредит».</li>\n<li>Почему параметры масштабирования оценивают только по обучающей\nвыборке? Что именно завышается, если это правило нарушить?</li>\n<li>Вы получили accuracy 0.93. Какие ещё два числа нужно знать, чтобы\nпонять, хороший это результат?</li>\n</ol>\n<hr />\n<p><strong>Дома:</strong> откройте <code>lab01_homework.ipynb</code> —\nтам две задачи: механизм пропусков и своя реализация One-Hot.</p>\n</div>\n</body>\n</html>\n'}}]);